import{_ as a,o,c as t,a2 as r}from"./chunks/framework.Desnpdez.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"help/faq.md","filePath":"help/faq.md"}'),s={name:"help/faq.md"};function n(i,e,d,h,l,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="what-is-mindbehindmcp" tabindex="-1">What is MindBehindMCP? <a class="header-anchor" href="#what-is-mindbehindmcp" aria-label="Permalink to &quot;What is MindBehindMCP?&quot;">​</a></h2><p>A Mac app that runs a local <strong>assistant bridge</strong> and lets you attach <strong>connections</strong> (tools and data) for use in assistants such as ChatGPT, Open WebUI, or other MCP-capable clients.</p><h2 id="do-i-need-docker" tabindex="-1">Do I need Docker? <a class="header-anchor" href="#do-i-need-docker" aria-label="Permalink to &quot;Do I need Docker?&quot;">​</a></h2><p><strong>Not for the bridge.</strong> A normal install includes the engine on your Mac.<br> Some <strong>Library</strong> presets show a <strong>Docker</strong> badge—only those presets need Docker installed.</p><h2 id="does-my-data-go-to-mindbehind-servers" tabindex="-1">Does my data go to MindBehind servers? <a class="header-anchor" href="#does-my-data-go-to-mindbehind-servers" aria-label="Permalink to &quot;Does my data go to MindBehind servers?&quot;">​</a></h2><p>Your documents and tool traffic stay on your Mac. The app still talks to the internet for things you expect: <strong>license checks</strong>, <strong>remote MCP endpoints</strong> you configured, <strong>OAuth</strong> in the browser, and optional <strong>Open WebUI sync</strong> when you turn it on.</p><h2 id="macos-only" tabindex="-1">macOS only? <a class="header-anchor" href="#macos-only" aria-label="Permalink to &quot;macOS only?&quot;">​</a></h2><p>Yes. There is no supported Windows or Linux build in this product line.</p><h2 id="where-is-my-configuration-stored" tabindex="-1">Where is my configuration stored? <a class="header-anchor" href="#where-is-my-configuration-stored" aria-label="Permalink to &quot;Where is my configuration stored?&quot;">​</a></h2><p><code>~/Library/Application Support/MindBehind/mcp-orchestrator/</code><br> See <strong><a href="./../reference/data-directory.html">Data directory</a></strong> for a file-by-file list.</p><h2 id="how-do-i-update" tabindex="-1">How do I update? <a class="header-anchor" href="#how-do-i-update" aria-label="Permalink to &quot;How do I update?&quot;">​</a></h2><p>Run the install command again or download the latest <code>.dmg</code> from the <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">public releases</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://halfcross.github.io/mbit-mcpo-proxy-download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><h2 id="can-i-import-from-claude-desktop" tabindex="-1">Can I import from Claude Desktop? <a class="header-anchor" href="#can-i-import-from-claude-desktop" aria-label="Permalink to &quot;Can I import from Claude Desktop?&quot;">​</a></h2><p>Yes. Copy the <code>mcpServers</code> block from <code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (or similar) and use <strong><a href="./../everyday/settings.html#import-json-mcpjson">Settings → Import JSON</a></strong>.</p><h2 id="need-more-help" tabindex="-1">Need more help? <a class="header-anchor" href="#need-more-help" aria-label="Permalink to &quot;Need more help?&quot;">​</a></h2><p>Open <strong><a href="./troubleshooting.html">Troubleshooting</a></strong> next.</p>',18)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
